#include "stdafx.h"#include "H_Class.h"static SBlockCreate HAICHANNEL( "HAICHANNEL", SH_HAICHANNEL::Create );SH_HAICHANNEL::SH_HAICHANNEL(): pSlave( NULL ){}#include <HPARM_INIT.h> #include "ParmVarInfo.h"LIST_PARM(SH_HAICHANNEL,W_HAICHANNEL,100)void SH_HAICHANNEL::InitParm(){#include "Blocks/HAICHANNEL.h"   s_defFlag = SVarInfo::efParam;#include "Blocks/HAICHANNEL_P.h"  qsort ( VarInfo, kVarInfo, sizeof ( SVarInfo ), CompVarInfo );}static LPCSTR s_ConPoint = "PV";LPCSTR SH_HAICHANNEL::SetDestIO( KBmBase *dest, LPCSTR pszField ){  if( this==dest )    return s_ConPoint;  eVarType type = evtHZ;  BYTE *pV = NULL;  bool b = dest->GetVar( s_ConPoint, &pV, &type );  ASS( b );  ASS( type==evtDouble );  pSlave = (double*)pV;  return s_ConPoint;}void SH_HAICHANNEL::StepT( SStepCalcParams &dt ){  if( pSlave )    *pSlave = W->PV;}